using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Coordinates;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Orbital;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Orbital;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Validation.OrbitalAndPositional;
public sealed class AstronomyOrbitalParametersValidationRuleTests { [Fact] public void Valid_parameters_pass() => Assert.Empty(new AstronomyOrbitalParametersValidationRule().Validate(OrbitalPositionalValidationFixture.ValidParameters(), OrbitalPositionalValidationFixture.Context())); [Fact] public void Same_parameter_at_different_epochs_is_allowed() { var payload = new AstronomyOrbitalParametersPayload(new("typed.orbital.parameters.v1"), OrbitalPositionalValidationFixture.OrbitalContext(), [OrbitalPositionalValidationFixture.Parameter(epoch: AstronomyEpochReference.Custom(new DateTimeOffset(2026,1,1,0,0,0,TimeSpan.Zero))), OrbitalPositionalValidationFixture.Parameter(epoch: AstronomyEpochReference.Custom(new DateTimeOffset(2026,2,1,0,0,0,TimeSpan.Zero)))]); Assert.DoesNotContain(new AstronomyOrbitalParametersValidationRule().Validate(payload, OrbitalPositionalValidationFixture.Context()), i => i.Code == AstronomyOrbitalValidationCodes.ParameterDuplicate); } [Fact] public void Duplicate_parameters_are_constructor_protected() { var p = OrbitalPositionalValidationFixture.Parameter(); Assert.Throws<ArgumentException>(() => new AstronomyOrbitalParametersPayload(new("typed.orbital.parameters.v1"), OrbitalPositionalValidationFixture.OrbitalContext(), [p, p])); } [Fact] public void Parameter_category_dimension_mismatch_detected() { var p = new AstronomyOrbitalParameter(new("orbital.period"), AstronomyOrbitalParameterCategory.Period, OrbitalPositionalValidationFixture.Measure(1, Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Measurements.AstronomyMeasurementDimension.Distance)); var payload = new AstronomyOrbitalParametersPayload(new("typed.orbital.parameters.v1"), OrbitalPositionalValidationFixture.OrbitalContext(), [p]); Assert.Contains(new AstronomyOrbitalParametersValidationRule().Validate(payload, OrbitalPositionalValidationFixture.Context()), i => i.Code == AstronomyOrbitalValidationCodes.ParameterDimensionMismatch); } }
